// static
bool StructTraits<::brave_vpn::mojom::ProductUrls::DataView, ::brave_vpn::mojom::ProductUrlsPtr>::Read(
    ::brave_vpn::mojom::ProductUrls::DataView input,
    ::brave_vpn::mojom::ProductUrlsPtr* output) {
  bool success = true;
  ::brave_vpn::mojom::ProductUrlsPtr result(::brave_vpn::mojom::ProductUrls::New());
  
      if (success && !input.ReadFeedback(&result->feedback))
        success = false;
      if (success && !input.ReadAbout(&result->about))
        success = false;
      if (success && !input.ReadManage(&result->manage))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::brave_vpn::mojom::PurchasedInfo::DataView, ::brave_vpn::mojom::PurchasedInfoPtr>::Read(
    ::brave_vpn::mojom::PurchasedInfo::DataView input,
    ::brave_vpn::mojom::PurchasedInfoPtr* output) {
  bool success = true;
  ::brave_vpn::mojom::PurchasedInfoPtr result(::brave_vpn::mojom::PurchasedInfo::New());
  
      if (success && !input.ReadState(&result->state))
        success = false;
      if (success && !input.ReadDescription(&result->description))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::brave_vpn::mojom::Region::DataView, ::brave_vpn::mojom::RegionPtr>::Read(
    ::brave_vpn::mojom::Region::DataView input,
    ::brave_vpn::mojom::RegionPtr* output) {
  bool success = true;
  ::brave_vpn::mojom::RegionPtr result(::brave_vpn::mojom::Region::New());
  
      if (success && !input.ReadName(&result->name))
        success = false;
      if (success && !input.ReadNamePretty(&result->name_pretty))
        success = false;
      if (success && !input.ReadCountry(&result->country))
        success = false;
      if (success && !input.ReadContinent(&result->continent))
        success = false;
      if (success && !input.ReadCountryIsoCode(&result->country_iso_code))
        success = false;
      if (success && !input.ReadRegionPrecision(&result->region_precision))
        success = false;
      if (success && !input.ReadCities(&result->cities))
        success = false;
      if (success)
        result->latitude = input.latitude();
      if (success)
        result->longitude = input.longitude();
      if (success)
        result->server_count = input.server_count();
      if (success)
        result->is_automatic = input.is_automatic();
      if (success && !input.ReadSmartRoutingProxyState(&result->smart_routing_proxy_state))
        success = false;
  *output = std::move(result);
  return success;
}

